const input = $input.first().json.body || $input.first().json;
if (!Array.isArray(input.meters)) throw new Error('meters must be an array');
const meters = input.meters.map((m) => ({ serial: String(m.meterSerialNumber || 'unknown'), type: m.meterType || 'UNKNOWN', unit: m.unitNumber || 'Unassigned', block: m.blockName || 'Unknown', protocol: m.protocol || 'UNKNOWN', status: m.status || 'UNKNOWN', reading: Number(m.lastReading || 0), lastTelemetryTime: m.lastTelemetryTime || null, batteryLevel: m.batteryLevel == null ? null : Number(m.batteryLevel), leakDetected: Boolean(m.leakDetected) }));
const counts = { total: meters.length, active: meters.filter(m => m.status === 'ACTIVE').length, offline: meters.filter(m => m.status === 'OFFLINE').length, fault: meters.filter(m => m.status === 'FAULT').length, tampered: meters.filter(m => m.status === 'TAMPERED').length, leakAlerts: meters.filter(m => m.leakDetected).length, lowBattery: meters.filter(m => m.batteryLevel != null && m.batteryLevel < 20).length };
const prompt = `Summarize this community smart meter fleet for an operations manager. Use only supplied records. Identify meter availability, leak indicators, low battery, stale telemetry and data gaps. Do not infer consumption fraud or issue device commands. Return JSON {"fleetStatus":"HEALTHY|ATTENTION|DEGRADED|INSUFFICIENT_DATA","summary":"...","priorityMeters":[{"serial":"...","issue":"...","priority":"HIGH|MEDIUM|LOW","recommendedCheck":"..."}],"dataQualityNotes":["..."],"nextChecks":["..."]}. Snapshot counters=${JSON.stringify(counts)} meters=${JSON.stringify(meters)}`;
return [{ json: { communityId: input.communityId ?? null, generatedAt: new Date().toISOString(), counts, meters, prompt } }];

const response = $input.first().json;
const source = $('Aggregate Fleet Snapshot').first().json;
let summary;
try { summary = JSON.parse(response.candidates[0].content.parts[0].text); } catch { summary = { fleetStatus: source.counts.offline + source.counts.fault + source.counts.tampered + source.counts.leakAlerts > 0 ? 'ATTENTION' : 'INSUFFICIENT_DATA', summary: 'AI summary unavailable. Review the meter dashboard and raw telemetry.', priorityMeters: source.meters.filter(m => m.status !== 'ACTIVE' || m.leakDetected || (m.batteryLevel != null && m.batteryLevel < 20)).map(m => ({ serial: m.serial, issue: m.leakDetected ? 'Leak alert from meter record' : `Meter status ${m.status}`, priority: m.status === 'TAMPERED' || m.leakDetected ? 'HIGH' : 'MEDIUM', recommendedCheck: 'Verify device state and recent telemetry with the operations team.' })), dataQualityNotes: [], nextChecks: ['Review meter dashboard readings.'] }; }
return [{ json: { status: 'success', communityId: source.communityId, generatedAt: source.generatedAt, counts: source.counts, summary } }];
